head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gAllChk = false;
scwin.gLdMktTp = js_market;
scwin.gTrnsType;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        scwin.initPage();
        txb_cnt.hide();
        rdo_MKT_ID.setValue(scwin.gLdMktTp);
        if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '6') {
            panel_mkt.hide();
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30320.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30320.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Confirm_onclick = async function() {
    try {
        if (await scwin.confirm() === true) {
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30320.btn_Confirm_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30320.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_TrstkSubmit_OnLoadCompleted
 * @description dts_TrstkSubmit 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_TrstkSubmit_OnLoadCompleted = async function(rowcount) {
    try {
        txb_totCnt.setValue("총건수 : " + rowcount);
        await scwin.getIsuCnt(dts_IsuCnt);
        txb_cnt.setValue(dts_IsuCnt.getCellData(0, "ISU_CNT"));
        txb_isu_cnt.setValue("종목 총건수 : " + txb_cnt.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30320.dts_TrstkSubmit_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_TrstkSubmit_OnLoadError
 * @description dts_TrstkSubmit 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_TrstkSubmit_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_TrstkSubmit);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30320.dts_TrstkSubmit_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_SelectedAll_onclick
 * @description 「전체선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SelectedAll_onclick = function() {
    try {
        scwin.selectAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30320.btn_SelectedAll_onclick" });
    }
};

/**
 * @method
 * @name btn_SDATE_onclick
 * @description btn_SDATE 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDATE_onclick = function() {
    try {
        popUpCalendar2(edt_SDATE);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30320.btn_SDATE_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let msg;
    if (edt_SDATE.getValue() === "") {
        msg = $c.stf.getMessageParam("MSG-A005", "신청일자");
        await $c.win.alert(msg);
        edt_SDATE.focus();
        return false;
    }

    // 초기화
    scwin.gAllChk === false;
    btn_SelectedAll.setValue("전체선택");
    let url = "";

    // 자사주 신청내역조회
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&SPOT_ISU_TRD_MKT_TP_CD=" + rdo_MKT_ID.getValue();
    url += "&SCREN_ID=" + "ULDSTF30320.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_TrstkSubmit",
        action : "/NoteMgt.do",
        ref : "",
        target : "dts_TrstkSubmit=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getPrevBzDt
 * @description 전 영업일 구하기
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getPrevBzDt = async function(dtsObj) {
    url += "&inputMessageId=BIZSPT_NOTE_PREVBZDT&outputMessageId=BIZSPT_NOTE_PREVBZDT";
    const sbmOptions = {
        id : "sbm_dtsObj",
        action : "/NoteMgt.do",
        ref : "",
        target : "dtsObj=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getIsuCnt
 * @description 종목 총 건수 구하기
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsuCnt = async function(dtsObj) {
    url += "&APPL_DT=" + edt_SDATE.getValue();
    url += "&MKT_ID=" + rdo_MKT_ID.getValue();
    url += "&inputMessageId=BIZSPT_NOTE_ISUCNT&outputMessageId=BIZSPT_NOTE_ISUCNT";
    const sbmOptions = {
        id : "sbm_dtsObj",
        action : "/NoteMgt.do",
        ref : "",
        target : "dtsObj=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    // fn_getPrevBzDt(dts_AgBzDd);
    // setObjectValue(edt_SDATE,  dts_AgBzDd.NameValue(0, "CALND_DD"));

    const ToDay = $c.ut.cGetToday2();
    edt_SDATE.setValue(ToDay);
};

/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {

};

/**
 * @method
 * @name confirm
 * @description opener에 값 선택된 값 전달.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function() {
    // opener에 값 선택된 값 전달.

    let total = 0;
    for (let i = 1; i <= dts_TrstkSubmit.getRowCount(); i++) {
        let chk = dts_TrstkSubmit.getCellData(i, "CHECK");
        if (chk === "T" || chk === "1") total++;
    }
    if (total === 0) {
        await $c.win.alert("수신자를 선택하세요.");
        return false;
    }
    frame.opener.grd_Receiver.setBroadcast(false);
    let j = 1 + frame.opener.dts_Receiver.getRowCount();
    dts_Receiver.setBroadcast(false);
    for (let i = 1; i <= dts_TrstkSubmit.getRowCount(); i++) {
        let chk = dts_TrstkSubmit.getCellData(i, "CHECK");
        const vLength = dts_TrstkSubmit.getCellData(i, "ENCRYP_ORDERER_CELLPHONE_NO").length;
        if (vLength > 0 && (chk === "T" || chk === "1")) {
            frame.opener.dts_Receiver.AddRow();
            frame.opener.dts_Receiver.setCellData(j, "CHECK", "T");
            frame.opener.dts_Receiver.setCellData(j, "COM_ABBRV", dts_TrstkSubmit.getCellData(i, "COM_ABBRV"));
            frame.opener.dts_Receiver.setCellData(j, "CHRG_NM", dts_TrstkSubmit.getCellData(i, "ORDERER_NM"));
            frame.opener.dts_Receiver.setCellData(j, "CELLPHONE_NO", dts_TrstkSubmit.getCellData(i, "ENCRYP_ORDERER_CELLPHONE_NO"));
            frame.opener.dts_Receiver.setCellData(j, "ISUR_CD", dts_TrstkSubmit.getCellData(i, "ISUR_CD"));
            frame.opener.dts_Receiver.setCellData(j, "EMAIL", dts_TrstkSubmit.getCellData(i, "TRSTK_APPL_DD"));
            // frame.opener.dts_Receiver.NameString(j, "EMAIL") = "-"

            j++;
        }
    }
    dts_Receiver.setBroadcast(true, true);
    // frame.opener.grd_TrstkSubmit.AutoResizeAllCol(true);
    frame.opener.grd_Receiver.setBroadcast(true);
    frame.opener.fn_RowCount();
    return true;
};

/**
 * @method
 * @name selectAll
 * @description select All 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectAll = function() {
    grd_TrstkSubmit.Redraw = false;
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        dts_TrstkSubmit.setBroadcast(false);
        for (let i = 0; i < dts_TrstkSubmit.getRowCount(); i++) {
            dts_TrstkSubmit.setCellData(i + 1, "CHECK", "T");
        }
        dts_TrstkSubmit.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        dts_TrstkSubmit.setBroadcast(false);
        for (let i = 0; i < dts_TrstkSubmit.getRowCount(); i++) {
            dts_TrstkSubmit.setCellData(i + 1, "CHECK", "F");
        }
        dts_TrstkSubmit.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체선택");
    }
    grd_TrstkSubmit.Redraw = true;
};
